import{_ as l,l as i,o as e,c as s,v as r,p as n,x as t,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const G=JSON.parse('{"title":"GLR","description":"","frontmatter":{"title":"GLR","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/glr-parser.md","filePath":"cs/glr-parser.md","lastUpdated":1789023840000}'),c={name:"cs/glr-parser.md"};function h(L,a,R,_,m,u){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="glr" tabindex="-1">GLR <a class="header-anchor" href="#glr" aria-label="Permalink to &quot;GLR&quot;">​</a></h1><div class="epigraph"><p>在 LR 表遇上冲突时复制栈，沿多条移进与归约走下去；子图共享使二义文法仍可交出分析森林。</p><footer>—— 据 Tomita, Efficient Parsing for Natural Language, 1986；bison 的 GLR 模式整理</footer></div><p>上一课<a href="/cs/earley-parser">Earley</a>在原 CFG 上做位置 DP，不借用已生成的 LALR 表。缺口是另一条通用路：<strong>GLR</strong>——确定时与 LALR 一样快，冲突才分叉。自然语言与部分程序语言（C++ 的病态局部）用这条。本课钉分叉与合并，不写 Tomita 的全部图栈细节。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>bison 默认遇冲突就选一个动作或报错。GLR：同一状态对同一记号可既移进又归约，则栈分裂；两条路若到达同一状态与同一输入位置，合并，避免指数重复。输出是共享紧凑的分析森林，而不是单棵树。缺口是<strong>在 LR 自动机上做非确定</strong>，不是再定义项。</p><p>相对 Earley：状态已是 LR 项集，扫描仍是查表；只在冲突格上非确定。文法接近 LR 时分叉少。</p><h3 id="森林不是「随便一棵」" tabindex="-1">森林不是「随便一棵」 <a class="header-anchor" href="#森林不是「随便一棵」" aria-label="Permalink to &quot;森林不是「随便一棵」&quot;">​</a></h3><p>二义必须在语义层消：优先级、最长匹配、或类型相关再分析（C++）。GLR 只保证不丢合法推导。把森林当唯一 AST 交给类型检查会炸。</p><p><span class="marginnote">Tomita 1986。GNU bison <code>%glr-parser</code> 是工程入口。Elkhound 等实现强调合并。本课不进入自然语言统计消歧。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生成 LR 表。确定动作则单栈；冲突则 GSS（图结构栈）上多路。归约在图上沿不同前驱弹出不同长度。共享节点：相同非终结符覆盖相同输入区间则复用。</p>',11)),(e(),n(E,null,{default:t(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LR%5B%22LR%20%E8%A1%A8%22%5D%20--%3E%20DET%5B%22%E7%A1%AE%E5%AE%9A%E5%8A%A8%E4%BD%9C%22%5D%0A%20%20LR%20--%3E%20SPLIT%5B%22%E5%86%B2%E7%AA%81%E5%88%99%E5%88%86%E5%8F%89%22%5D%0A%20%20SPLIT%20--%3E%20MERGE%5B%22%E5%90%8C%E7%8A%B6%E6%80%81%E5%90%8C%E4%BD%8D%E7%BD%AE%E5%90%88%E5%B9%B6%22%5D%0A%20%20MERGE%20--%3E%20FOR%5B%22%E5%88%86%E6%9E%90%E6%A3%AE%E6%9E%97%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>C++ 需lookahead 与类型的交叉时，GLR 仍可能要「试探再拒」；那是语言的上下文相关，不是 CFG 的失败。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最坏仍与一般 CFL 同阶；平均看冲突密度。reduce/reduce 在 GLR 里是合法分叉，不像 yacc 里几乎总是文法错误。内存：森林共享失败会爆。</p><p>与 PEG 后课对照：GLR 认真正的 CFG 并集；PEG 的 <code>/</code> 是有序选择，不是并。不要把 bison 的 GLR 模式当成 PEG。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 GLL 写完，不算 Tomita 与 Earley 的常数比。不处理增量。后课默认：冲突可分叉的 LR 叫 GLR；下一课换形式体系——PEG 与 packrat，不再用产生式并。</p><p>错误恢复在多栈上更难，后课单独收。此处假定输入合法或失败则整片拒。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GLR：LR 表 + 冲突分叉 + 栈合并。</li><li>输出森林；消二义在语义，不在表的 <code>%left</code> alone。</li><li>近 LR 时便宜，真二义时换空间。</li><li>出处：Tomita, 1986；bison GLR；对照 Earley, 1970。</li></ul>',9))])}const f=l(c,[["render",h]]);export{G as __pageData,f as default};
